window.FILM_WORK_PROMPTS={"work_id":"src-9a8ec7af63ece74f","records":[{"work_id":"src-9a8ec7af63ece74f","frame_id":"FG-43184514720ae4d5","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/07 (1330).jpg","source_page":"https://film-grab.com/2013/06/28/sightseers/","scene":"高速公路俯瞰视角，多车道上车辆稀疏行驶，左侧有红色卡车，右侧是砖墙和茂密树林，天空多云。","analysis":"画面采用高角度俯视构图，道路呈对角线延伸，占据画面主体。前景右下角可见黑色监控设备，中景为多辆行驶中的汽车和卡车，远景是树木和天空。光线柔和，色彩以灰绿和土黄为主，呈现出阴天的自然光感。","prompt":"高角度俯瞰高速公路，多车道沥青路面呈对角线延伸，白色虚线清晰。左侧车道有一辆红色平板卡车，中间车道有白色轿车和货车行驶。右侧路边是高大的砖砌挡土墙，墙后是茂密的绿色和黄色树林。前景右下角有一个黑色的监控摄像头装置。天空多云，光线均匀柔和，整体色调偏冷，呈现出阴天的公路场景。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T15:25:31-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/07 (1330).jpg","observed_dimensions":[1280,544],"source_thumbnail_dimensions":[500,213],"source_image_match_mae":0.508,"observed_resolution":"normal","observation_limits":[],"id":"VP-99ae750c5e0ff55f","origin":"visual"},{"work_id":"src-9a8ec7af63ece74f","frame_id":"FG-e6a8855963054a5e","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/20 (1357).jpg","source_page":"https://film-grab.com/2013/06/28/sightseers/","scene":"黄昏时分的开阔原野，左侧前景矗立着一棵巨大的落叶乔木，枝干向右侧伸展。中景是连绵起伏的深色树林与灌木丛，远处地平线隐约可见起伏的山丘轮廓，天空呈现柔和的金黄色调。","analysis":"画面采用横向构图，左侧前景的树木占据约三分之一画面宽度，形成视觉框架。中景树林呈深褐色剪影状，与明亮的天空形成强烈明暗对比。光线从右上方照射，天空呈现从金黄到淡橙的渐变层次，云层稀薄。整体视角平视，景深较大，前景树木细节清晰，远景逐渐虚化融入暮色中。","prompt":"黄昏原野风景，左侧前景一棵巨大的落叶乔木，树干粗壮，枝条向右侧伸展，树叶稀疏呈深褐色剪影。中景是连绵的深色树林和灌木丛，呈现起伏的轮廓线。远处地平线可见模糊的山丘和城镇轮廓。天空占据画面上半部分，呈现柔和的金黄色到淡橙色渐变，云层稀薄呈水平条纹状。光线从右上方照射，整体色调温暖，前景树木与中景树林形成剪影效果，地面是平坦的草地，呈现暗绿色调。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T15:25:39-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/20 (1357).jpg","observed_dimensions":[1280,544],"source_thumbnail_dimensions":[500,213],"source_image_match_mae":0.514,"observed_resolution":"normal","observation_limits":[],"id":"VP-6d7c0d03624381cd","origin":"visual"},{"work_id":"src-9a8ec7af63ece74f","frame_id":"FG-134872c83db332e7","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/33 (1354).jpg","source_page":"https://film-grab.com/2013/06/28/sightseers/","scene":"一只白色长毛狗的后脑勺占据画面中心，颈部佩戴深棕色皮质项圈。背景为极度虚化的室内环境，可见模糊的暖色光斑、深色家具轮廓及左侧的垂直亮区。","analysis":"构图采用中心对称，焦点完全集中在狗头顶蓬松的白色毛发上，质感清晰可见。背景通过大光圈虚化处理，形成柔和的散景，将主体与复杂的室内环境分离。光线柔和，整体色调偏暖，背景中隐约可见红褐色与米黄色的色块，营造出一种安静、专注的视觉氛围。","prompt":"一只白色长毛狗的后脑勺特写，毛发蓬松且细节丰富，颈部系着深棕色皮质项圈。背景为高度虚化的室内场景，呈现出柔和的散景效果，包含模糊的暖色光斑、深色家具轮廓以及左侧的垂直亮区。画面色调温暖，焦点清晰地落在狗头顶的毛发上，营造出一种安静、专注的视觉氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T15:25:46-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/33 (1354).jpg","observed_dimensions":[1280,544],"source_thumbnail_dimensions":[500,213],"source_image_match_mae":0.523,"observed_resolution":"normal","observation_limits":[],"id":"VP-058537af7ba16119","origin":"visual"},{"work_id":"src-9a8ec7af63ece74f","frame_id":"FG-831cb4a8773664ca","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/46 (1327).jpg","source_page":"https://film-grab.com/2013/06/28/sightseers/","scene":"画面左侧为一名蓄着浓密络腮胡的男性面部侧面特写，背景是大面积虚化的暖黄色光斑与模糊的室内环境。","analysis":"构图极度偏左，人物面部占据画面左侧约三分之一，右侧为大面积虚化背景。仅可见人物头部侧面，视线平视前方。光线柔和，面部处于阴影中，背景由多个圆形暖色光斑组成，呈现出强烈的景深效果，光色层次丰富，从暗部到亮部过渡自然。","prompt":"画面左侧为一名蓄着浓密络腮胡的男性面部侧面特写，仅可见头部轮廓，视线平视前方。背景是大面积虚化的室内环境，由多个圆形暖黄色光斑组成，呈现出强烈的景深效果。光线柔和，面部处于阴影中，与背景明亮的散景形成对比。整体色调偏暖，营造出一种静谧、沉思的氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T15:25:52-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/46 (1327).jpg","observed_dimensions":[1280,544],"source_thumbnail_dimensions":[500,213],"source_image_match_mae":0.513,"observed_resolution":"normal","observation_limits":[],"id":"VP-08c68b00014951d1","origin":"visual"},{"work_id":"src-9a8ec7af63ece74f","frame_id":"FG-dcc1dab14d597204","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/59 (1217).jpg","source_page":"https://film-grab.com/2013/06/28/sightseers/","scene":"房车内部，一男一女相对而坐。男子穿灰色毛衣，女子穿深蓝色上衣，中间木桌上摆放着酒瓶和酒杯，背景是挂着棕色窗帘的车窗。","analysis":"画面采用平视视角，构图平衡。左侧男子呈侧坐姿态，上半身及大腿可见，身体前倾；右侧女子背对镜头侧坐，上半身可见，低头看向下方。两人之间的小木桌占据画面中心，桌上有绿色酒瓶和透明高脚杯。背景是房车窗户，挂着厚重的棕色窗帘，窗外光线柔和，室内光线均匀，色调偏暖。","prompt":"房车内部场景，左侧一名留着络腮胡的男子身穿灰色针织毛衣和卡其色长裤，侧身坐在桌边，双臂交叠在桌面上。右侧一名深色头发的女子身穿深蓝色上衣，背对镜头坐在铺有花纹织物的座位上。两人中间是一张浅色木质折叠桌，桌上摆放着三个深绿色玻璃酒瓶、三个装有浅色液体的高脚杯和一个红色装饰瓶。背景是房车的大窗户，挂着厚重的棕色窗帘，窗外可见模糊的自然景色。左侧前景可见房车厨房台面和抽屉，整体光线柔和自然，色调温暖，呈现出一种安静的室内氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T15:26:01-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/59 (1217).jpg","observed_dimensions":[1280,544],"source_thumbnail_dimensions":[500,213],"source_image_match_mae":0.524,"observed_resolution":"normal","observation_limits":[],"id":"VP-1b0ccdd966e35de1","origin":"visual"}]};